package java.util.concurrent.atomic;
public class AtomicReference<V> implements java.io.Serializable {private volatile V value;public AtomicReference(){}public AtomicReference(V v){value=v;}public final V get(){return value;}public final void set(V v){value=v;}public final void lazySet(V v){set(v);}public final synchronized V getAndSet(V v){V old=value;value=v;return old;}public final synchronized boolean compareAndSet(V e,V v){if(value!=e)return false;value=v;return true;}public final boolean weakCompareAndSet(V e,V v){return compareAndSet(e,v);}public String toString(){return String.valueOf(value);} public final synchronized V getAndUpdate(java.util.function.UnaryOperator<V> f){V old=value; value=f.apply(old); return old;} public final synchronized V updateAndGet(java.util.function.UnaryOperator<V> f){return value=f.apply(value);} public final synchronized V getAndAccumulate(V x,java.util.function.BinaryOperator<V> f){V old=value; value=f.apply(old,x); return old;} public final synchronized V accumulateAndGet(V x,java.util.function.BinaryOperator<V> f){return value=f.apply(value,x);} }
